static void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
static void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);}
static QByteArray read(const QString &path){QFile f(path);require(f.open(QIODevice::ReadOnly),"Tracking-file artifact unavailable");return f.readAll();}
static void write(const QString &path,const QByteArray &data){QFile f(path);require(f.open(QIODevice::WriteOnly)&&f.write(data)==data.size(),"Tracking-file artifact write failed");}
static QString hash(const QString &path){return QCryptographicHash::hash(read(path),QCryptographicHash::Sha256).toHex();}
static QStringList names(const QString &name){auto *object=Moderator::Instance()->GetConfiguredObject(name.toStdString());require(object,"Tracking resource missing");QStringList result;for(const auto &p:object->GetStringArrayParameter("FileName"))result.append(QString::fromStdString(p));return result;}
static void replace(QString &source,const QString &key,const QString &value){const QRegularExpression expression("^"+QRegularExpression::escape(key)+"\\s*=[^;\\n]*;",QRegularExpression::MultilineOption);require(expression.match(source).hasMatch(),"Shipped tracking assignment missing");source.replace(expression,key+" = "+value+";");}
static QList<double> numbers(const QByteArray &raw){QList<double> result;for(const auto &field:QString::fromUtf8(raw).trimmed().split(',')){bool ok=false;const double value=field.trimmed().toDouble(&ok);require(ok&&std::isfinite(value),"Tracking state report nonfinite");result.append(value);}require(result.size()==15&&result.last()==41,"Tracking state report cardinality/sentinel wrong");return result;}
static void same(const QList<double> &a,const QList<double> &b){require(a.size()==b.size(),"Tracking result cardinality changed");for(int i=0;i<a.size();++i)require(std::abs(a[i]-b[i])<1e-8,"Tracking file route changed numeric results");}
